-- Field-check status is distinct from scientific specimen identification.
CREATE TABLE natural_history_audits(object_id TEXT PRIMARY KEY REFERENCES collection_objects(object_id), audit_version INTEGER NOT NULL, source_hashes_json TEXT NOT NULL CHECK(json_valid(source_hashes_json)), fields_json TEXT NOT NULL CHECK(json_valid(fields_json)), issues_json TEXT NOT NULL CHECK(json_valid(issues_json)), academic_review TEXT NOT NULL DEFAULT 'NEEDS_REVIEW' CHECK(academic_review IN('NEEDS_REVIEW','EXPERT_REVIEWED')), reviewer TEXT, CHECK(academic_review!='EXPERT_REVIEWED' OR reviewer IS NOT NULL));
CREATE TABLE natural_knowledge(knowledge_id TEXT PRIMARY KEY, subject_name TEXT NOT NULL, field_name TEXT NOT NULL, value_json TEXT NOT NULL CHECK(json_valid(value_json)), scope TEXT NOT NULL CHECK(scope='TYPE_KNOWLEDGE_NOT_SPECIMEN_MEASUREMENT'), authority_url TEXT NOT NULL, checked_at TEXT NOT NULL, review_status TEXT NOT NULL CHECK(review_status='DRAFT_PENDING_REVIEW'));
